package io.github.some_example_name;
import io.github.some_example_name.database.*;import io.github.some_example_name.model.*;import java.util.*;
public final class DraftClass2003RegressionTest{public static void main(String[]a){require(DraftClassRepository.hasHistoricalClass(2003),"not registered");List<Player>ps=DraftClassRepository.getClassForYear(2003);require(ps.size()==60,"Expected 60");Set<String>old=new HashSet<>();for(int y=1970;y<=2002;y++)for(Player p:DraftClassRepository.getClassForYear(y))old.add(n(p.getName()));Map<String,Player>m=new HashMap<>();for(Player p:ps){require(p.getAge()==18,"age "+p.getName());require(!old.contains(n(p.getName())),"Repeated "+p.getName());require(m.put(p.getName(),p)==null,"Duplicate "+p.getName());}expect(m,"Cristiano Ronaldo",Position.RW,76,70,32,91,91,99);expect(m,"Ashley Young",Position.LW,68,70,39,90,80,91);expect(m,"Mark Milligan",Position.CB,43,62,67,87,59,80);System.out.println("Draft class 2003: 60 unique prospects with pre-balanced potential OK.");}private static String n(String s){return s.toLowerCase(Locale.ROOT);}private static void expect(Map<String,Player>m,String n,Position q,int a,int p,int d,int f,int dr,int pot){Player x=m.get(n);require(x!=null&&x.getPrimaryPosition()==q&&x.getPotential()==pot&&x.getTechnicalAttributes().getAtaque()==a&&x.getTechnicalAttributes().getPasse()==p&&x.getTechnicalAttributes().getDefesa()==d&&x.getTechnicalAttributes().getFisico()==f&&x.getTechnicalAttributes().getDrible()==dr,"Bad "+n);}private static void require(boolean b,String s){if(!b)throw new AssertionError(s);}}
